script.setup:
const s=ctx.state,gl=ctx.gl;
s.program=ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER,"#version 300 es
precision highp float;
#define GLSLIFY 1
in vec2 v_uv;out vec4 outColor;uniform vec2 u_resolution;uniform sampler2D u_image;
uniform float u_radius;
uniform int u_mode;
struct Intersection {
  float t0;
  float t1;
  int hits; // forward hits
  bool isInside;
};

// Finds the intersection of a ray with a sphere.
// origin is the ray origin relative to the sphere
// ray is the ray direction (normalized)
// radius is the sphere radius
//
// Implements the algorithm described here that bypasses precision issues:
// "Precision Improvements for Ray/Sphere Intersection"
// By: Eric Haines, Johannes Gunther, and Tomas Akenine-Moller
// https://link.springer.com/content/pdf/10.1007/978-1-4842-4427-2_7.pdf
Intersection sphereIntersection(vec3 origin, vec3 ray, float radius) {
  float b = -dot(origin, ray);
  vec3 w = origin + b * ray;
  float r2 = radius * radius;
  float d = r2 - dot(w, w);
  if(d < 0.0) {
    return Intersection(0.0, 0.0, 0, false);
  }
  if(d == 0.0) {
    return Intersection(b, b, 1, false);
  }
  float c = dot(origin, origin) - r2;
  float sqrtd = sqrt(d);
  float q = b + sign(b) * sqrtd;
  float t0 = c / q;
  float t1 = q;
  int hits = int(t0 >= 0.0) + int(t1 > 0.0);
  return Intersection(min(t0, t1), max(t0, t1), hits, c < 0.0);
}

void main(){vec2 uv=v_uv,p=(uv*2.-1.)*u_resolution/min(u_resolution.x,u_resolution.y);vec3 color;vec3 ro=vec3(0,0,2.6),rd=normalize(vec3(p,-2.));Intersection hit=sphereIntersection(ro,rd,u_radius);color=vec3(.035,.075,.13);if(hit.hits>0){vec3 n=normalize(ro+rd*hit.t0);color=u_mode==0?n*.5+.5:mix(vec3(.15,.27,.65),vec3(1,.75,.3),clamp((hit.t1-hit.t0)/(2.*u_radius),0.,1.));}
outColor=vec4(color,1);}");
